def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        if '+' in core:
            core = core.split('+', 1)[0]
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def cmp_key(v):
        major, minor, patch, pre_ids = parse(v)
        if pre_ids is None:
            pre_key = (1,)
        else:
            parts = []
            for ident in pre_ids:
                if ident.isdigit():
                    parts.append((0, int(ident), ''))
                else:
                    parts.append((1, 0, ident))
            pre_key = (0, len(pre_ids), tuple(parts))
        return (major, minor, patch, pre_key)

    return sorted(versions, key=cmp_key)

